syntax:
template <class Type> class ClassName { /* class definition */ }; // General template

// Full specialization
template <> class ClassName<SpecificType> { /* specialized implementation */ };

// Partial specialization (for class templates)
template <class T> class ClassName<T*> { /* specialized for pointer types */ };

code_example:
#include <iostream>
template <typename Mutex>
class shared_lock {
public:
    explicit shared_lock(Mutex& m) : mutex_(m) {
        mutex_.lock_shared();
    }
    ~shared_lock() {
        mutex_.unlock_shared();
    }
private:
    Mutex& mutex_;
};

// Specialization for a specific Mutex type
class shared_timed_mutex {
public:
    void lock_shared() { std::cout << "Shared lock acquired" << std::endl; }
    void unlock_shared() { std::cout << "Shared lock released" << std::endl; }
};

int main() {
    shared_timed_mutex mtx;
    shared_lock<shared_timed_mutex> lock(mtx);
    // lock is acquired upon creation and released when going out of scope
    return 0;
}
